import json
from pathlib import Path
p=Path('dist/data.json');d=json.loads(p.read_text());by={n['name']:n['id'] for n in d['nodes']}
def q(dim,prompt,answer,hint,cap,exp=None):return dict(dim=dim,prompt=prompt,answer=answer,hint=hint,cap=cap,expected=exp)
for name in ['乘法分配律','列方程解决问题','三角形面积','面积单位换算','平均数的意义','三角形分类']:
 sets=[]
 for t in range(3):
  if name=='乘法分配律':
   a=6+t*5;b=14+t;c=6-t;total=a*(b+c)
   qs=[q('基本操作',f'计算：{a}×({b}＋{c})。',str(total),f'分别求{a}×{b}与{a}×{c}。',4,[str(total)]),q('结构识别',f'计算：{a}×{b}＋{a}×{c}。不要逐项做复杂乘法。',f'{a}×({b}＋{c})={total}。','提取共同因数。',4,[str(total)]),q('表示转换',f'画长方形解释{a}×({b}＋{c})与分开计算的关系。',f'共同宽{a}，两段长为{b}与{c}，面积和等于整体面积{total}。','给长方形画一条分割线。',2),q('条件边界',f'有人写{a}×({b}＋{c})={a}×{b}＋{c}，指出并改正错误。',f'第二项应为{a}×{c}，每一组的两部分都重复{a}次。','共同因数要乘到每一项。',3),q('推理解释', ['用“几组物品”的故事解释分开乘再相加为何不改变总数。','解释为什么相同因数可以提到括号外，括号里的数表示什么。','设x、y、z是数，解释xy＋xz=x(y＋z)与图形、数量表示之间的共同结构。'][t], '要点：相同的份数或每份量被保留；各部分不重复、不遗漏；图或故事与算式一一对应。','先指出共同的一份或共同份数。',3),q('迁移检验',f'两种物品分别买{b}件与{c}件，每件都{a}元。用两种方法求总价并解释为何相同。',f'分别算价后相加，或先求件数{b+c}再乘单价{a}，总价{total}元。','比较两种方法中的不变量。',7)]
  elif name=='列方程解决问题':
   a=3+t;b=7+t;x=9+t;total=a*x+b
   qs=[q('基本操作',f'解方程：{a}x＋{b}={total}。只填写x。',str(x),'先两边同时减去常数，再同除以系数。',3,[str(x)]),q('关系建模',f'每盒有x支笔，{a}盒再加{b}支共{total}支。每盒有多少支？',f'{a}x＋{b}={total}，x={x}。','先按题意建立等量关系。',1,[str(x)]),q('表示转换',f'用线段图解释{a}x＋{b}={total}中每一部分。',f'{a}段相同的未知量，加一段{b}，合计{total}。','不要把多出的部分也画进每一份。',2),q('条件边界',f'同学把“{a}倍再多{b}”写成{a}(x＋{b})，说明错误并改正。',f'应为{a}x＋{b}，原式把多出的{b}也重复了{a}次。','比较先增加再倍乘与先倍乘再增加。',3),q('推理解释',['解释对等式两边同时减去同一个数为何保持相等。','解释解方程时用到的逆运算，并把得到的解代回原式。','如果把每盒量限制为正整数，怎样检查代数解满足情境？再举一个方程有解但情境不允许的例子。'][t],f'当前解为{x}，代回{a}×{x}＋{b}={total}。需说明操作同时作用于两边，且除数非0；情境还限制正整数。','分别检查代数关系和实际取值。',3),q('迁移检验',f'编一道与{a}x＋{b}={total}关系相同、生活背景不同的题，并说明未知量、单位和检验。','应对应若干份相同量与额外一部分，关系和单位一致；通过代入原问题验证。','可以换成装书、路程或购物。',7)]
  elif name=='三角形面积':
   base=10+2*t;high=6+2*t;area=base*high//2
   qs=[q('基本操作',f'底{base}厘米、对应高{high}厘米的三角形，面积多少平方厘米？',str(area),'用底乘对应高的一半。',3,[str(area)]),q('逆向结构',f'面积{area}平方厘米、对应高{high}厘米，底多少厘米？',str(base),'先把面积乘2，还原底高乘积。',4,[str(base)]),q('表示转换',f'画图或描述两个全等三角形如何拼成面积{area*2}平方厘米的平行四边形。',f'拼后底{base}、高{high}，面积{area*2}；原图占一半。','比较拼前拼后的覆盖范围。',2),q('条件边界','一个三角形换用另一条边作底时，能保留原来的高不变吗？举例或画图说明。','通常不能；每条底对应自己的垂直高，面积相同但底高需要匹配。','从对面顶点向所选底所在直线作垂线。',3),q('推理解释',['解释三角形面积为什么不能只用底乘高。','同一底上顶点沿平行线移动，解释形状变化与面积不变的原因。','两个三角形面积相等时，底与高的比怎样互相关联？用具体数举例，不把面积相等误说成全等。'][t],'要点：面积由底乘对应高的一半决定；相同乘积可来自不同底高组合，不能直接反推形状相同。','用等积与底高乘积组织解释。',3),q('迁移检验',f'三角形底{base}米、高{high}米，每平方米需2元维护费。先求总费，再检查单位。',f'面积{area}平方米，费用{area*2}元；面积单位与单价中的平方米约去。','分清面积计算与费用计算两个环节。',6)]
  elif name=='面积单位换算':
   a=4+t;val=a*100;side=2+t
   qs=[q('基本操作',f'{a}平方米等于多少平方分米？',str(val),'平方米到平方分米进率100。',3,[str(val)]),q('结构识别',f'{val}平方分米等于多少平方米？',str(a),'按100个平方分米一组分。',3,[str(a)]),q('表示转换',f'边长{side}米的正方形，用米和分米两种单位分别求面积并核对。',f'{side*side}平方米；边长{side*10}分米，面积{side*side*100}平方分米。','长度变为10倍数值，面积对应100倍数值。',2),q('错误边界','有人说“换成更小的面积单位，面积就变大了”。这句话混淆了什么？','同一块面大小未变，变大的是用较小单位表示时的数值。','把物理的量和数字区分。',3),q('推理解释',['用10行10列单位方格解释平方单位进率。','说明为什么平方厘米到平方米不能只除以100。','比较长度、面积、体积相应单位的进率，为何分别是一、二、三次方？'][t],'量的维度决定计数方式；面积要同时沿两个方向计数，不能直接套长度进率。','先找出每个方向有多少个小单位。',3),q('迁移检验',f'长{a}米、宽2米的地面，使用边长2分米的方砖。分别按面积和行列数计算砖数。',f'面积{a*2*100}平方分米，每块4平方分米，需{a*50}块；沿长{a*5}块、宽10块。假设能整齐铺满、无缝无损耗。','两种方法应得到相同数，检查能否整除。',7)]
  elif name=='平均数的意义':
   mid=8+4*t;arr=[mid-3,mid,mid+3];total=3*mid
   qs=[q('基本操作',f'{arr[0]}、{arr[1]}、{arr[2]}的平均数是多少？',str(mid),'求和再除以数据个数。',3,[str(mid)]),q('结构识别',f'3个数平均{mid}，加入一个{mid+8}，4个数平均多少？',str(mid+2),'先还原三个数总和。',5,[str(mid+2)]),q('表示转换',f'用移多补少解释{arr}这组数的平均数。',f'从{arr[2]}移3给{arr[0]}，三个量都等于{mid}；总量不变。','画三根高低不同的条。',2),q('错误边界','某组2人平均10，另一组6人平均18，合并平均数能直接取14吗？','不能；总和20＋108=128，总人数8，平均16。','分组平均数代表的人数不同。',3),q('推理解释',['解释平均数为何不一定是某一次实际记录。','一组数每个都增加5，平均数也增加5，说明总量与个数怎样变化。','把两组平均数直接平均，在哪个条件下成立？说明为何人数相等时成立，并给不等人数的反例。'][t],'需通过总量和个数解释，不凭“中间数”外观；分组人数相同才可直接等权平均。','问每个平均数代表多少个数据。',3),q('迁移检验',f'前3天平均读书{mid}页，第4天读{mid+8}页。用总量和移多补少两种想法解释四天平均数。',f'总量{4*(mid+2)}页，平均{mid+2}页；新一天多出的8页分到四天，每天多2。','别把3天平均和1天读数直接平均。',7)]
  else:
   vertex=40+20*t;other=(180-vertex)//2
   qs=[q('基本识别',f'等腰三角形顶角{vertex}度，每个底角多少度？',str(other),'两个底角相等，三个内角和180度。',3,[str(other)]),q('条件应用',f'一个三角形两个角是{other}度与{vertex}度，第三个角多少度？',str(other),'180减去已知两角之和。',3,[str(other)]),q('表示转换','用图或包含关系说明等边三角形为什么也是等腰三角形。','三边都相等，自然满足至少两边相等；等边是等腰的特殊类型。','按定义检查，避免把“至少”理解为“恰好”。',2),q('边界辨析','把锐角三角形放倒或旋转，是否可能变为钝角三角形？说明判断标准。','不能，旋转保持角度，按角分类不依赖纸面朝向。','看角度，别看有没有水平的边。',3),q('推理解释',['按边分与按角分为什么可以同时描述一个三角形？','等腰三角形有一个角是30度，其余两个角有哪些可能？','等腰三角形有一个角是90度，为什么只能是顶角？用内角和排除另一种假设。'][t],['两种分类选择不同标准，彼此可以交叉。','30作顶角：75、75；30作底角：30、120。','若90为底角，另一个底角也是90，第三角为0，不能构成三角形。'][t],'分清按什么性质分类，必要时分类讨论。',0),q('检验反思','给出一个“等腰但不是锐角”的三角形，用角度和边角性质检查它。','例：40、40、100度，角和180度，两底角相等对应等腰，同时有钝角。','构造相等的两角，再检查第三角。',7)]
  sets.append(qs)
 d['banks'][by[name]]['alternate']=sets
p.write_text(json.dumps(d,ensure_ascii=False));print('Added',sum(len(t) for b in d['banks'].values() for t in b['alternate']),'alternate tasks')
